Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

long long power[20];
int minimum_moves;

long long get_leading_digit(long long number, int &length) {
    length = 0;
    while (number >= 10) {
        number /= 10;
        length++;
    }
    return number;
}

void explore(long long current, int count) {
    if (count >= minimum_moves) return;
    if (current == 0) {
        minimum_moves = count;
        return;
    }
    int len;
    int leading_digit = get_leading_digit(current, len);
    explore(abs(current - power[len] * leading_digit), count + leading_digit * (len + 1));
    if (leading_digit - 1 > 0)
        explore(abs(current - power[len] * (leading_digit - 1)), count + (leading_digit - 1) * (len + 1));
    if (leading_digit > 1)
        explore(abs(power[len + 1] - current), count + (len + 2));
}

int main() {
    long long number;
    scanf("%lld", &number);
    power[0] = 1;
    for (int i = 1; i <= 18; i++) {
        power[i] = power[i - 1] * 10 + 1;
    }
    minimum_moves = 1e9;
    explore(number, 0);
    printf("%d\n", minimum_moves);
    return 0;
}
